// Forum image selection handler
const selectForumImage = url => {
    document.getElementById('imageURL').value = url;
    document.getElementById('forumImagePreview').innerHTML = `<img src="${url}" style="max-width: 100%; height: auto; display: block; border-radius: 4px; margin-top: 8px;">`;

    // Update header preview
    const headerPreview = document.getElementById('headerForumImagePreview');
    const headerImg = document.getElementById('headerForumImage');
    if (headerImg && headerPreview) {
        headerImg.src = url;
        headerPreview.style.display = 'block';
    }

    const modal = bootstrap.Modal.getInstance(document.getElementById('insertImageModal'));
    if (modal) modal.hide();
};

// Load forum images when modal is shown
document.addEventListener('DOMContentLoaded', () => {
    const imageModal = document.getElementById('insertImageModal');
    if (imageModal) {
        imageModal.addEventListener('show.bs.modal', () => {
            loadForumImages();
        });
    }
});

// Load images from API for forum
const loadForumImages = async () => {
    try {
        const response = await fetch('/api/images');
        const images = await response.json();
        const imageList = document.getElementById('imageList');

        if (!images || images.length === 0) {
            imageList.innerHTML = '<div class="text-center text-body-secondary py-4"><small>Nenhuma imagem disponível</small></div>';
            return;
        }

        let html = '';
        images.forEach(img => {
            html += `<div class="d-flex gap-2 mb-2 p-2 forum-image-row" style="border-bottom: 1px solid var(--bs-border-color); cursor: pointer;" data-url="${img.file_url}">`;
            html += `<div style="width: 60px; height: 60px; flex-shrink: 0; border-radius: 0.25rem; overflow: hidden; display: flex; align-items: center; justify-content: center; background-color: var(--bs-body-bg);">`;
            html += `<img src="${img.file_url}" alt="${img.display_name}" style="width: 100%; height: 100%; object-fit: contain;">`;
            html += `</div>`;
            html += `<div class="flex-grow-1">`;
            html += `<div class="small fw-bold">${img.display_name}</div>`;
            html += `<div class="small text-body-secondary text-truncate">${img.description || 'Sem descrição'}</div>`;
            html += `<div class="small text-body-secondary">${img.created_at || ''}</div>`;
            html += `</div>`;
            html += `<button type="button" class="btn btn-sm btn-outline-primary forum-select-image-btn" data-url="${img.file_url}" style="white-space: nowrap;">Usar</button>`;
            html += `</div>`;
        });
        imageList.innerHTML = html;

        // Attach event listeners for image rows (click anywhere on the row to select)
        document.querySelectorAll('.forum-image-row').forEach(row => {
            row.addEventListener('click', function (e) {
                // Prevent button click from being handled twice
                if (e.target.classList.contains('forum-select-image-btn')) {
                    return;
                }
                selectForumImage(this.getAttribute('data-url'));
            });
        });

        // Also keep button click handler as fallback
        document.querySelectorAll('.forum-select-image-btn').forEach(btn => {
            btn.addEventListener('click', function () {
                selectForumImage(this.getAttribute('data-url'));
            });
        });
    } catch (error) {
        console.error('Erro ao carregar imagens:', error);
        document.getElementById('imageList').innerHTML = '<div class="alert alert-danger mb-0">Erro ao carregar imagens</div>';
    }
};

// Upload handling for the form
document.addEventListener('DOMContentLoaded', () => {
    const uploadForm = document.getElementById('uploadImageForm');
    if (uploadForm) {
        uploadForm.addEventListener('submit', async function (e) {
            e.preventDefault();
            const file = document.getElementById('imageFileInput').files[0];
            if (!file) {
                document.getElementById('uploadImageStatus').innerHTML = '<div class="alert alert-warning mb-0">Selecione uma imagem</div>';
                return;
            }

            const uploadBtn = document.getElementById('uploadImageBtn');
            const uploadStatus = document.getElementById('uploadImageStatus');

            uploadStatus.innerHTML = '<div class="alert alert-info mb-0">Enviando...</div>';
            uploadBtn.disabled = true;

            const formData = new FormData();
            formData.append('file', file);
            formData.append('original_filename', file.name);
            formData.append('description', document.getElementById('imageDescription').value || file.name);
            formData.append('filetag', 'forum');

            try {
                const response = await fetch('/files/upload', {
                    method: 'POST',
                    body: formData
                });
                const html = await response.text();

                if (html.indexOf('alert-danger') !== -1 || html.indexOf('error') !== -1 || html.indexOf('Error') !== -1) {
                    uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload. Verifique o tamanho do arquivo (máx. 500 MB).</div>';
                } else {
                    uploadStatus.innerHTML = '<div class="alert alert-success mb-0">Upload concluído. Recarregando lista...</div>';
                    document.getElementById('imageFileInput').value = '';
                    document.getElementById('imageDescription').value = '';
                    setTimeout(() => {
                        loadForumImages();
                        uploadStatus.innerHTML = '';
                    }, 1500);
                }
            } catch (error) {
                console.error('Erro ao fazer upload:', error);
                uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload: ' + error + '</div>';
            } finally {
                uploadBtn.disabled = false;
            }
        });
    }

    // Handle URL insertion
    const insertUrlImageBtn = document.getElementById('insertUrlImageBtn');
    if (insertUrlImageBtn) {
        insertUrlImageBtn.addEventListener('click', function () {
            const url = document.getElementById('imageUrlInput').value.trim();
            if (url) {
                selectForumImage(url);
            }
        });
    }
});
